import{_ as t,o as e,c as s,a2 as a}from"./chunks/framework.BXzK3EA4.js";const g="/assets/134_71c9a633-6863-4f22-b79a-72acbcae1a89.YVTM30qv.png",r="/assets/135_263602305e108b75e830f45f0e598deb.De50ZGWM.png",u=JSON.parse('{"title":"域名注册信息要求","description":"","frontmatter":{"title":"域名注册信息要求"},"headers":[],"relativePath":"ops-knowledge-base/sales-issues/domain-registration-requirements.md","filePath":"ops-knowledge-base/sales-issues/domain-registration-requirements.md","lastUpdated":1788259091000}'),o={name:"ops-knowledge-base/sales-issues/domain-registration-requirements.md"};function i(n,p,_,d,m,c){return e(),s("div",null,[...p[0]||(p[0]=[a('<p>一.注册域名前，请按如下信息修改账户信息，使账户信息符合域名注册信息要求。</p><p>1.点击右上角头像</p><p>2.点击我的资料</p><p>3.名字不能为空，只能使用英文或拼音</p><p>4.姓氏不能为空，只能使用英文或拼音</p><p>5.公司名称可以为空，如填写，只能用英文或拼音</p><p>6.邮件地址必需填写合法有效地址，需要接收验证邮件来激活域名</p><p>7.街道地址第一行不能为空，只能用英文，拼音，数字</p><p>8.街道地址第二行可以不填，如填写，只能用英文，拼音，数字</p><p>9.城市，必填，只能使用英文或拼音，且必需 国家&gt;&gt;省份&gt;&gt;城市 对应</p><p>10.省份，必填，只能使用英文或拼音，且必需 国家&gt;&gt;省份 对应</p><p>11.国家，必选</p><p>12.邮编，必填，只能使用英文或拼音，且必需 国家&gt;&gt;省份&gt;&gt;城市&gt;&gt;邮编 对应</p><p>13.手机号码，必填，并确保与所选地区的相关编码规则匹配。</p><p><img src="'+g+'" alt=""></p><p>二.注册域名时，如下图，需要新建或选择联系人信息。</p><p>1.点击帮助中心，可查看域名信息相关要求</p><p>2.新建或选择联系人信息，如果之前没有创建过联系人信息，首次注册域名必需新建一个联系人信息，如果之前有，可以直接点击选择。</p><p>3.名字不能为空，只能使用英文或拼音</p><p>4.姓氏不能为空，只能使用英文或拼音</p><p>5.公司名称可以为空，如填写，只能用英文或拼音</p><p>6.邮件地址必需填写合法有效地址，需要接收验证邮件来激活域名</p><p>7.街道地址第一行不能为空，只能用英文，拼音，数字</p><p>8.街道地址第二行可以不填，如填写，只能用英文，拼音，数字</p><p>9.城市，必填，只能使用英文或拼音，且必需 国家&gt;&gt;省份&gt;&gt;城市 对应</p><p>10.省份，必填，只能使用英文或拼音，且必需 国家&gt;&gt;省份 对应</p><p>11.国家，必选</p><p>12.邮编，必填，只能使用英文或拼音，且必需 国家&gt;&gt;省份&gt;&gt;城市&gt;&gt;邮编 对应</p><p>13.手机号码，必填，并确保与所选地区的相关编码规则匹配。</p><p><img src="'+r+'" alt=""></p><p>三、重要提示</p><p>域名注册信息必需符合上述相关要求</p><p>国家&gt;&gt;省份&gt;&gt;城市&gt;&gt;邮编 必需对应，否则注册无法通过！</p>',33)])])}const f=t(o,[["render",i]]);export{u as __pageData,f as default};
